  +
  (1 3) \cdot \{ t \}
  +
  (2 4) \cdot \{ t \}
  +
  (1 3) (2 4) \cdot \{t\}.
\end{align*}

Then
\begin{align*}
  \operatorname{Irrep}_{(w,..,w)}
  := \operatorname{span}\{ e_t : t \text{ Young tableau of shape } (w,..,w) \}
\end{align*}
is an irreducible representation of $S_n$ and
\begin{align*}
  \{ e_t : t \text{ standard Young tableau of shape $(w,..,w)$}  \},
\end{align*}
forms a basis \cite[Theorem 2.5.2]{bib:Sag2013}.
This concludes the reminder on representation theory for $S_n$.



















Define the map $\iota$ from the space of tabloids of shape $(w,..,w)$ into $V^{\otimes n}$ as follows,

\begin{align*}
  \iota( \{ t \} )
  :=
  e_{j_1}^* \otimes .. \otimes e_{j_n}^*,
\end{align*}
where $e_i^*$ is the canonical basis of $V$ and
\begin{align*}
  j_\ell = i \qquad \Leftrightarrow \qquad \ell \in \text{ $i$-th row of } \{ t \}.
\end{align*}
For example
\begin{align*}
  \iota\left(
