  e_1^* \otimes e_1^* \otimes e_2^* \otimes e_2^* \otimes e_1^* \otimes e_2^*.
\end{align*}
This is a homomorphism of $S_n$ representations.
Indeed,
\begin{align*}
  \iota( \tau \cdot \{t\} )
  =
  e_{j_1}^* \otimes .. \otimes e_{j_n}^*,
\end{align*}
with
\begin{align*}
  j_\ell = i &\Leftrightarrow \ell \in \text{ $i$-th row of } \tau \cdot \{t\}.

\end{align*}




On the other hand
\begin{align*}
  \tau \cdot \iota( \{t\} )
  &=
  \tau \cdot e_{r_1}^* \otimes .. \otimes e_{r_n}^* \\
  &=

  e_{p_1}^* \otimes .. \otimes e_{p_n}^*,
\end{align*}
with $p_\ell := r_{\tau^{-1}(\ell)}$
and
\begin{align*}
  p_\ell = i &\Leftrightarrow r_{\tau^{-1}(\ell)} = i \\
             &\Leftrightarrow \tau^{-1}(\ell) \in \text{ $i$-th row of } \{t\} \\
